package studio.otherstuff.ambulando.core.identitybackup

import studio.otherstuff.ambulando.core.crypto.Nip49
import studio.otherstuff.ambulando.core.nostr.Bech32
import java.text.Normalizer

/** Where an on-device identity came from. Only a key generated by this app is [NEW]; imports and recoveries are [EXISTING]. */
enum class IdentityOrigin(val wire: String) {
    NEW("new"), EXISTING("existing"),
    /** The device's record of where the key came from is present but unreadable. Fails closed: treated like NEW until a hosted copy is proven. */
    UNKNOWN("new");

    /** Payment needs a proven hosted backup first. Only a recorded or legacy-absent EXISTING origin is exempt. */
    val needsBackup: Boolean get() = this != EXISTING
}

/** NStack's immutable, first-claim-wins username (hosted-identity-backup-v1): NFKC, lowercase, 3..32 of `[a-z0-9_-]`. */
object BackupUsername {
    private val SHAPE = Regex("^[a-z0-9][a-z0-9_-]{1,30}[a-z0-9]$")
    private val RESERVED = setOf("admin", "support", "nstack", "wingman", "root", "system")

    /** The exact form the server will store, or null when it would be refused (`400 invalid_username`). */
    fun normalize(raw: String): String? {
        if (raw.length > 64) return null
        val text = Normalizer.normalize(raw.trim(), Normalizer.Form.NFKC).lowercase()
        return text.takeIf { SHAPE.matches(it) && it !in RESERVED }
    }
}

/**
 * Shape of the opaque NIP-49 ciphertext NStack stores. Checked before sending and on everything received, with the length
 * test first so no untrusted long string reaches the Bech32 decoder.
 */
object BackupCiphertext {
    const val LENGTH = 162
    const val MIN_LOG_N = 16
    const val MAX_LOG_N = 18
    const val DEFAULT_LOG_N = 16

    fun isWellFormed(text: String): Boolean {
        if (text.length != LENGTH || !text.startsWith("ncryptsec1") || text != text.lowercase()) return false
        val decoded = Bech32.decode(text) ?: return false
        val p = decoded.data
        return decoded.hrp == Nip49.HRP && p.size == Nip49.PAYLOAD_BYTES && (p[0].toInt() and 0xff) == Nip49.VERSION &&
            (p[1].toInt() and 0xff) in MIN_LOG_N..MAX_LOG_N && (p[2 + 16 + 24].toInt() and 0xff) in 0..2
    }
}

/** Why a chosen backup password is refused locally. NStack never checks strength, so this is the only guard. */
enum class PasswordProblem(val message: String) {
    TOO_SHORT("Use at least 16 characters. A long, unique phrase of several words is best; anyone can try to guess it offline."),
    TOO_SIMPLE("That is too easy to guess. Mix words, numbers or symbols, or use a longer phrase."),
    CONTAINS_USERNAME("Do not build the password from your username."),
    MISMATCH("The two passwords are not the same."),
}

object BackupPassword {
    /** Creating a hosted backup: anyone can fetch the ciphertext by username and guess offline, so the floor is high. Recovery never applies it. */
    const val MIN_LENGTH = 16
    const val MAX_LENGTH = 256
    private val COMMON = listOf("password", "passw0rd", "qwerty", "letmein", "123456", "iloveyou", "welcome", "nostr", "bitcoin", "ambulando")

    /** Null when acceptable. Length counts code points of the NFKC form, the same bytes scrypt will see. */
    fun problem(password: CharSequence, confirmation: CharSequence, username: String?): PasswordProblem? {
        val text = Normalizer.normalize(password, Normalizer.Form.NFKC)
        if (text != Normalizer.normalize(confirmation, Normalizer.Form.NFKC)) return PasswordProblem.MISMATCH
        val points = text.codePointCount(0, text.length)
        if (points < MIN_LENGTH) return PasswordProblem.TOO_SHORT
        if (points > MAX_LENGTH) return PasswordProblem.TOO_SIMPLE
        val lower = text.lowercase()
        if (username != null && username.length >= 3 && lower.contains(username.lowercase())) return PasswordProblem.CONTAINS_USERNAME
        if (text.toSet().size < 6 || text.all { it.isDigit() } || COMMON.any { lower.replace(" ", "").startsWith(it) && points < 20 }) return PasswordProblem.TOO_SIMPLE
        return null
    }
}

/** A classified hosted-backup failure. Messages never carry ciphertext, passwords or response bodies. */
class BackupFailure(val kind: Kind, val status: Int? = null, val code: String? = null, val retryAfterSeconds: Int? = null) :
    Exception(kind.name, null, false, false) {
    enum class Kind {
        BACKEND_MISSING, INVALID_USERNAME, INVALID_BACKUP, WEAK_PASSWORD, SIGNER_REFUSED, OWNER_MISMATCH, USERNAME_UNAVAILABLE,
        ALREADY_BACKED_UP, REVISION_CONFLICT, RATE_LIMITED, NOT_FOUND, WRONG_PASSWORD, VERIFY_FAILED, IDENTITY_LOCKED, IDENTITY_MISMATCH,
        SERVER, NETWORK, MALFORMED, PERSISTENCE, COST_TOO_HIGH,
    }

    var problem: PasswordProblem? = null
        private set

    fun withProblem(p: PasswordProblem) = apply { problem = p }

    override fun equals(other: Any?) = other is BackupFailure && other.kind == kind && other.status == status && other.code == code
    override fun hashCode() = kind.hashCode() * 31 + (code?.hashCode() ?: 0)

    val userMessage: String
        get() = when (kind) {
            Kind.BACKEND_MISSING -> "This NStack does not offer identity backups."
            Kind.INVALID_USERNAME -> "Choose a username of 3 to 32 letters, numbers, hyphens or underscores, starting and ending with a letter or number."
            Kind.INVALID_BACKUP -> "The backup could not be made in the form NStack accepts."
            Kind.WEAK_PASSWORD -> problem?.message ?: "Choose a stronger password."
            Kind.SIGNER_REFUSED -> "This NStack did not accept the signature. Check the unlocked identity."
            Kind.OWNER_MISMATCH -> "That username belongs to another identity."
            Kind.USERNAME_UNAVAILABLE -> "That username is taken. Choose another."
            Kind.ALREADY_BACKED_UP -> "This identity already has a hosted backup under another username."
            Kind.REVISION_CONFLICT -> "The hosted backup changed elsewhere. Check again before continuing."
            Kind.RATE_LIMITED -> "Too many attempts right now." + (retryAfterSeconds?.let { " Try again in about $it seconds." } ?: " Try again shortly.")
            Kind.NOT_FOUND -> "No hosted backup was found for that username."
            Kind.WRONG_PASSWORD -> "Wrong password, or the backup was altered."
            Kind.VERIFY_FAILED -> "The hosted copy could not be proven to unlock with your password and this identity, so it is not counted. Try again."
            Kind.IDENTITY_LOCKED -> "Unlock your identity first."
            Kind.IDENTITY_MISMATCH -> "The identity unlocked now is not the one being backed up. Nothing was sent."
            Kind.SERVER -> "NStack had a problem (HTTP ${status ?: 0}). Your backup was not confirmed. Try again shortly."
            Kind.NETWORK -> "Could not reach NStack. Your backup was not confirmed; try again."
            Kind.MALFORMED -> "NStack sent an unexpected answer. Your backup was not confirmed."
            Kind.PERSISTENCE -> "This device could not save the backup progress, so nothing further was sent. Free some space and try again."
            Kind.COST_TOO_HIGH -> "This backup asks for more memory than this app will spend on a password."
        }

    companion object {
        fun classify(status: Int, code: String?, retryAfter: Int?): BackupFailure {
            val kind = when {
                (status == 404 && code == null) || status == 405 -> Kind.BACKEND_MISSING
                code == "backup_not_found" -> Kind.NOT_FOUND
                code == "invalid_username" -> Kind.INVALID_USERNAME
                code == "invalid_backup" || code == "invalid_json" || code == "body_too_large" -> Kind.INVALID_BACKUP
                code == "backup_owner_mismatch" -> Kind.OWNER_MISMATCH
                code == "username_unavailable" -> Kind.USERNAME_UNAVAILABLE
                code == "identity_already_backed_up" -> Kind.ALREADY_BACKED_UP
                code == "revision_conflict" -> Kind.REVISION_CONFLICT
                status == 429 -> Kind.RATE_LIMITED
                status == 401 || status == 403 -> Kind.SIGNER_REFUSED
                else -> Kind.SERVER
            }
            return BackupFailure(kind, status, code, retryAfter)
        }
    }
}

/** What NStack answered to a write or a signed read. Revisions are decimal strings, never narrowed to Int. */
data class HostedBackupReceipt(val username: String, val revision: String)

data class HostedBackupCopy(val username: String, val ncryptsec: String, val revision: String)

/**
 * What the onboarding wizard needs to know about the signing identity. A [IdentityOrigin.NEW] key may not start payment until
 * NStack itself confirms a durable hosted copy; an existing key is never gated.
 */
interface IdentityBackupGate {
    val origin: IdentityOrigin
    /** Local, synchronous: is a confirmed hosted copy recorded on this device? Drives what the screen offers, never opens payment. */
    fun locallyConfirmed(): Boolean
    /** Asks NStack (signed). Anything other than a positive answer is false. */
    suspend fun confirmedOnServer(): Boolean

    companion object {
        val EXISTING: IdentityBackupGate = object : IdentityBackupGate {
            override val origin = IdentityOrigin.EXISTING
            override fun locallyConfirmed() = true
            override suspend fun confirmedOnServer() = true
        }
    }
}
